Explanation of correctness
- Each operation corresponds to reversing a consecutive block of siblings at some node and toggling those subtrees by r; since we can toggle any subtree individually (reverse a block of length 1), toggles do not constrain possible child orders.
- Thus, at each node, any permutation of its children is attainable, and subtrees act independently. Counting distinct strings equals counting distinct plane orderings of the same unordered rooted tree, multiplied by the independent counts inside children, yielding the recurrence used.
- The canonical unordered-shape ID ensures correct grouping of identical children to apply the multinomial factor.

Solution idea:

- View the directed graph defined by edges i → A_i. This is a functional graph, so each weakly connected component consists of exactly one directed cycle with trees feeding into the cycle nodes.
- Along any directed edge i → A_i we require y_i ≤ y_{A_i}. On a directed cycle, going all the way around forces all y-values on the cycle to be equal.
- For each node v, let children(v) be the set {u | A_u = v}. For nodes not on a cycle, these form rooted trees oriented toward the root (the node closer to the cycle).
- For a rooted tree with root r and an upper bound t on the root’s value, define:
  - For a leaf: F_leaf(t) = t.
  - In general: F_v(t) = sum_{k=1..t} product_{u in children(v)} F_u(k).
  This counts the number of ways to assign values to the subtree rooted at v such that all constraints hold and y_v ≤ t.
- For a cycle node c, let B_c(t) = product over its tree-children u (i.e., u with A_u = c and u not on a cycle) of F_u(t). If there are no such children, B_c(t) = 1.
- In a component whose cycle nodes are c_1, ..., c_L, since all cycle values must be equal to some s ∈ [1..M], the number of valid assignments for the component is:
  Sum_{t=1..M} Product_{j=1..L} B_{c_j}(t).
- The total number of arrays is the product of these sums over all components, modulo 998244353.

We can compute F for non-cycle nodes by peeling the trees using the usual queue with in-degree (number of children) zero, ensuring children are processed before parents. Each F_v is an array of size M with the recurrence above, which overall runs in O(N·M) time since the total number of child edges summed over all v is O(N). Then compute B_c for cycle nodes, group nodes into cycles, evaluate the sums, and multiply over components.

C++17 implementation:

```cpp
#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    if (!(cin >> N >> M)) return 0;
    vector<int> A(N);
    for (int i = 0; i < N; ++i) {
        cin >> A[i];
        --A[i]; // to 0-based
    }

    // Build children lists (incoming edges)
    vector<vector<int>> children(N);
    vector<int> indeg(N, 0);
    for (int i = 0; i < N; ++i) {
        children[A[i]].push_back(i);
    }
    for (int i = 0; i < N; ++i) indeg[i] = (int)children[i].size();

    // Peel off non-cycle nodes using queue of indeg==0
    queue<int> q;
    vector<char> removed(N, false);
    for (int i = 0; i < N; ++i) if (indeg[i] == 0) q.push(i);

    // DP arrays F for non-cycle nodes: F[v][t] = sum_{k=1..t} prod_{u child of v} F[u][k]
    vector<vector<long long>> F(N); // only filled for removed (non-cycle) nodes

    while (!q.empty()) {
        int v = q.front(); q.pop();
        removed[v] = true;

        // Compute F[v]
        vector<long long> f(M + 1, 0);
        // For each k, compute product over children u of F[u][k]
        // Note: all children must already be removed, so their F is known
        for (int k = 1; k <= M; ++k) {
            long long prod = 1;
            for (int u : children[v]) {
                // u must be removed (non-cycle)
                prod = (prod * F[u][k]) % MOD;
            }
            f[k] = (f[k - 1] + prod) % MOD; // prefix sum over k
        }
        F[v] = move(f);

        int to = A[v];
        indeg[to]--;
        if (indeg[to] == 0) q.push(to);
    }

    // Nodes with indeg > 0 are on cycles
    vector<char> on_cycle(N, false);
    for (int i = 0; i < N; ++i) if (!removed[i]) on_cycle[i] = true;

    // For each cycle node v, compute B[v][t] = product over non-cycle children u of F[u][t]
    vector<vector<long long>> B(N);
    for (int v = 0; v < N; ++v) if (on_cycle[v]) {
        vector<long long> b(M + 1, 1); // we'll use indices 1..M; b[0]=1 unused
        for (int t = 1; t <= M; ++t) {
            long long prod = 1;
            for (int u : children[v]) {
                if (!on_cycle[u]) {
                    prod = (prod * F[u][t]) % MOD;
                }
            }
            b[t] = prod;
        }
        B[v] = move(b);
    }

    // Traverse cycles and compute contributions
    vector<char> vis(N, false);
    long long ans = 1;
    for (int i = 0; i < N; ++i) if (on_cycle[i] && !vis[i]) {
        // Collect this cycle
        vector<int> cyc;
        int cur = i;
        while (!vis[cur]) {
            vis[cur] = true;
            cyc.push_back(cur);
            cur = A[cur];
        }
        // For this cycle, sum over t of product of B[v][t]
        long long sum = 0;
        for (int t = 1; t <= M; ++t) {
            long long prod = 1;
            for (int v : cyc) {
                prod = (prod * B[v][t]) % MOD;
            }
            sum += prod;
            if (sum >= MOD) sum -= MOD;
        }
        ans = (ans * sum) % MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}
```

This runs in O(N·M) time and O(N·M) memory, which fits comfortably for N, M ≤ 2025.

Solution idea:
- For a subarray, the minimal number of erase-steps equals the number of runs of consecutive integers among the distinct values present. That equals:
  g(L, R) = (# of distinct values in S[L..R]) − (# of t such that both t and t+1 appear in S[L..R]).

So the required sum is:
  SumDistinct − SumAdj,
where
- SumDistinct = sum over all subarrays of the number of distinct values,
- SumAdj = sum over t=1..N−1 of the number of subarrays that contain both t and t+1.

Efficient computation:
- Let pos[v] be the list of indices where value v occurs.
- Total number of subarrays: tot = N*(N+1)/2.

1) SumDistinct:
For each value v with occurrences p1 < p2 < ... < pk,
the number of subarrays that contain v is:
  contains[v] = sum_{j=1..k} p_j * (next_j − p_j),
where next_j = p_{j+1} if j<k else N+1.
SumDistinct = sum_v contains[v].

2) SumAdj:
For each t in 1..N−1, we need the number of subarrays that contain both t and t+1.
By inclusion-exclusion:
  both(t) = tot − miss_t − miss_{t+1} + miss_{t,t+1}
          = contains[t] + contains[t+1] − tot + miss_{t,t+1}
since miss_x = tot − contains[x].
Here miss_{t,t+1} is the number of subarrays that contain neither t nor t+1.
To get miss_{t,t+1}, merge the sorted lists pos[t] and pos[t+1], and sum over the gaps between consecutive occurrences (including ends):
  If gaps (lengths) are g1, g2, ..., then
  miss_{t,t+1} = sum_i g_i * (g_i + 1) / 2.
Total SumAdj is sum of both(t) over t.

Total complexity: O(N), since each occurrence is processed O(1) times across all merges.

Code (C++17):

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;
    vector<int> S(N+1);
    for (int i = 1; i <= N; ++i) cin >> S[i];

    vector<vector<int>> pos(N+2);
    for (int i = 1; i <= N; ++i) pos[S[i]].push_back(i);

    long long tot = 1LL * N * (N + 1) / 2;

    // contains[v]: number of subarrays that contain at least one v
    vector<long long> contains(N+2, 0);
    long long sumDistinct = 0;
    for (int v = 1; v <= N; ++v) {
        const auto &p = pos[v];
        int k = (int)p.size();
        for (int j = 0; j < k; ++j) {
            int nextIdx = (j + 1 < k) ? p[j+1] : (N + 1);
            contains[v] += 1LL * p[j] * (nextIdx - p[j]);
        }
        sumDistinct += contains[v];
    }

    auto miss_ab = [&](const vector<int>& a, const vector<int>& b) -> long long {
        long long res = 0;
        int i = 0, j = 0;
        int prev = 0;
        while (i < (int)a.size() || j < (int)b.size()) {
            int nxt;
            if (j == (int)b.size() || (i < (int)a.size() && a[i] < b[j])) {
                nxt = a[i++];
            } else {
                nxt = b[j++];
            }
            long long gap = 1LL * (nxt - prev - 1);
            if (gap > 0) res += gap * (gap + 1) / 2;
            prev = nxt;
        }
        long long gap = 1LL * (N - prev);
        if (gap > 0) res += gap * (gap + 1) / 2;
        return res;
    };

    long long sumAdj = 0;
    for (int t = 1; t <= N-1; ++t) {
        long long miss_ab_cnt = miss_ab(pos[t], pos[t+1]);
        long long both = contains[t] + contains[t+1] - tot + miss_ab_cnt;
        sumAdj += both;
    }

    long long ans = sumDistinct - sumAdj;
    cout << ans << '\n';
    return 0;
}
