    queue<int> q;
    vector<char> removed(N+1, false);
    for (int i = 1; i <= N; ++i) if (indeg[i] == 0) q.push(i);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        removed[u] = true;
        int v = A[u];
        indeg[v]--;
        if (indeg[v] == 0) q.push(v);
    }
    vector<char> is_cycle(N+1, false);
    for (int i = 1; i <= N; ++i) is_cycle[i] = !removed[i];

    // DP for non-cycle nodes: S[u][t], t=1..M
    vector<vector<int>> S(N+1, vector<int>(M+1, 0));
    vector<char> vis(N+1, 0);
    function<void(int)> dfs = [&](int u) {
        if (vis[u] || is_cycle[u]) return;
        vis[u] = 1;
        // process children first (they are non-cycle as argued)
        for (int v : children[u]) if (!is_cycle[v]) dfs(v);
        // compute H[y] = product over non-cycle children v of S[v][y]
        vector<int> H(M+1, 1);
        for (int v : children[u]) {
            if (is_cycle[v]) continue;
            for (int y = 1; y <= M; ++y) {
                H[y] = mulmod(H[y], S[v][y]);
            }
        }
        // S[u][t] = sum_{y=1..t} H[y]
        int acc = 0;
        for (int t = 1; t <= M; ++t) {
            acc = addmod(acc, H[t]);
            S[u][t] = acc;
        }
    };

    for (int i = 1; i <= N; ++i) {
        if (!is_cycle[i] && !vis[i]) dfs(i);
    }

    // Iterate over cycles and compute their contributions
    vector<char> visCycle(N+1, false);
    long long answer = 1;
    for (int i = 1; i <= N; ++i) {
        if (!is_cycle[i] || visCycle[i]) continue;
        // collect cycle starting from i
        vector<int> cyc;
        int u = i;
        do {
            cyc.push_back(u);
            visCycle[u] = true;
            u = A[u];
        } while (u != i);

        // For each node in cycle, compute H_i(t) = product over non-cycle children v of S_v(t)
        int k = (int)cyc.size();
        vector<vector<int>> Hs; Hs.reserve(k);
        for (int node : cyc) {
            vector<int> Hi(M+1, 1);
            for (int v : children[node]) {
                if (is_cycle[v]) continue;
                for (int t = 1; t <= M; ++t) {
                    Hi[t] = mulmod(Hi[t], S[v][t]);
                }
            }
            Hs.push_back(move(Hi));
        }
        // cycle contribution: sum_{t=1..M} prod_{idx} Hs[idx][t]
        long long contrib = 0;
        for (int t = 1; t <= M; ++t) {
            long long prod = 1;
            for (int idx = 0; idx < k; ++idx) {
                prod = (prod * Hs[idx][t]) % MOD;
            }
            contrib += prod;
            if (contrib >= MOD) contrib -= MOD;
        }
        answer = (answer * contrib) % MOD;
    }

    cout << answer % MOD << "\n";
    return 0;
}
```

Notes:
- The leaf-stripping step identifies cycle nodes reliably in a functional graph.
- For non-cycle nodes, their children are also non-cycle, so the DP remains straightforward.
- For each cycle, all cycle nodes must share the same value t; the total contributions for that cycle are obtained by summing over t the product of subtree contributions H_i(t) for all cycle nodes i in that cycle.
- The final answer is the product of all cycle contributions, modulo 998244353.

Idea:
The string can be reduced to empty by repeatedly deleting adjacent pairs "()", "[]", or "<>" if and only if the string is properly reducible by a standard stack algorithm for multiple bracket types.

Algorithm:
- Use a stack (vector).
- Scan the string left to right.
  - If the top of the stack is an opening bracket and the current character is its matching closing bracket, pop the stack.
  - Otherwise, push the current character onto the stack.
- At the end, if the stack is empty, the string is reducible (answer Yes); otherwise, No.

This runs in O(n) time and O(n) space.

Rust (1.56) implementation:

```rust
use std::io::{self, Read};

fn main() {
    // Read entire input
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let s = input.trim();

    let mut stack: Vec<u8> = Vec::with_capacity(s.len());

    for &b in s.as_bytes() {
        if let Some(&top) = stack.last() {
            if (top == b'(' && b == b')')
                || (top == b'[' && b == b']')
                || (top == b'<' && b == b'>')
            {
                stack.pop();
                continue;
            }
        }
        stack.push(b);
    }

    if stack.is_empty() {
        println!("Yes");
    } else {
        println!("No");
    }
}
```

This handles strings up to 2×10^5 characters efficiently.

Idea:
- Each constraint B[X_i] xor B[Y_i] = Z_i is a bitwise XOR constraint. Bit k contributes independently: the k-th bit of B[X_i] xor B[Y_i] must equal the k-th bit of Z_i.
- For each bit k, build a graph on N nodes with the M edges (X_i, Y_i) labeled by t_i = the k-th bit of Z_i. The equations are b_u xor b_v = t_i for each edge.
- This system is solvable iff every cycle has XOR-sum 0 of the t_i along the cycle. If solvable, each connected component has exactly two solutions (flip all bits in the component). To minimize the number of 1-bits in this bit, choose the flip that minimizes the count of 1s in that component.
- Do this independently for every bit up to the highest bit used in Z. Combine the bits to form B, ensuring the total sum is minimized.

Algorithm:
1. Build the undirected graph with N nodes and M edges. Store edge endpoints and Z_i.
2. Compute connected components of the graph (ignoring Z_i). Let compNodes[c] be the list of nodes in component c.
3. For each bit k from 0 to highestBit-1:
   - For every component, run a BFS/DFS to assign base values val[node] ∈ {0,1} such that for every edge (u,v) with t_i = (Z_i >> k) & 1 we have val[u] xor val[v] = t_i.
   - If a conflict is found (val[v] != val[u] xor t_i for an edge), no solution exists → output -1.
   - For each component, with size s and cnt1 = sum of val over nodes in the component, we can either keep val as is (giving cnt1 ones) or flip the entire component (giving s - cnt1 ones). Choose the smaller.
   - Set the bit k in B[u] accordingly (val[u] xor flip for each node u in the component).
4. Print B if feasible.

Complexity:
- Let C be the number of components. Each bit processes every edge once. If maxZ has B bits (B ≤ ~30 for Z ≤ 1e9), time is O((N + M) * B), which fits the limits. Memory is O(N + M).

Swift 5.5 implementation:

```swift
import Foundation

// Fast scanner
final class FastScanner {
    private var data: [UInt8] = Array(FileHandle.standardInput.readDataToEndOfFile()) + [0]
    private var idx: Int = 0

    func readInt() -> Int {
        var sign = 1
        var num = 0
        var c = data[idx]
        while c == 10 || c == 13 || c == 32 { idx += 1; c = data[idx] } // skip whitespace
        if c == 45 { sign = -1; idx += 1; c = data[idx] } // '-'
        while c >= 48 {
            num = num * 10 + Int(c - 48)
            idx += 1
            c = data[idx]
        }
        return num * sign
    }
}

let scanner = FastScanner()
let N = scanner.readInt()
let M = scanner.readInt()

var X = [Int](repeating: 0, count: M)
var Y = [Int](repeating: 0, count: M)
var Z = [Int](repeating: 0, count: M)

for i in 0..<M {
    X[i] = scanner.readInt()
    Y[i] = scanner.readInt()
    Z[i] = scanner.readInt()
}

// Build graph
var adj = Array(repeating: [(to: Int, idx: Int)](), count: N)
if M > 0 {
    for i in 0..<M {
        let u = X[i] - 1
        let v = Y[i] - 1
        adj[u].append((to: v, idx: i))
        adj[v].append((to: u, idx: i))
    }
}

// Compute connected components (ignoring weights)
var compId = Array(repeating: -1, count: N)
var compNodes: [[Int]] = []
for i in 0..<N {
    if compId[i] != -1 { continue }
    let cid = compNodes.count
    var q: [Int] = [i]
    compId[i] = cid
    var head = 0
    var nodes: [Int] = []
    while head < q.count {
        let u = q[head]
        head += 1
        nodes.append(u)
        for (to, _) in adj[u] {
            if compId[to] == -1 {
                compId[to] = cid
                q.append(to)
            }
        }
    }
    compNodes.append(nodes)
}

// Determine highest bit needed
let maxZ = Z.max() ?? 0
var highestBit = 0
var ttmp = maxZ
while ttmp > 0 {
    highestBit += 1
    ttmp >>= 1
}
// B as 64-bit to be safe
var B = Array(repeating: Int64(0), count: N)

if highestBit > 0 {
    // Process bits 0 .. highestBit-1
    for bit in 0..<highestBit {
        var val = Array(repeating: -1, count: N)
        var ok = true

        for c in 0..<compNodes.count {
            let nodes = compNodes[c]
            let root = nodes[0]
            if val[root] != -1 { continue } // already assigned in this bit (shouldn't happen)
            // BFS for this component
            var q: [Int] = [root]
            val[root] = 0
            var head = 0
            var cnt1 = 0

            while head < q.count && ok {
                let u = q[head]
                head += 1
                cnt1 += val[u]

                for (to, eidx) in adj[u] {
                    let t = (Z[eidx] >> bit) & 1
                    if val[to] == -1 {
                        val[to] = val[u] ^ t
                        q.append(to)
                    } else {
                        if val[to] != (val[u] ^ t) {
                            ok = false
                            break
                        }
                    }
                }
            }
            if !ok { break }

            let compSize = nodes.count
            let flip = (cnt1 <= compSize - cnt1) ? 0 : 1

            for u in nodes {
                let bitVal = val[u] ^ flip
                if bitVal == 1 {
                    B[u] |= (Int64(1) << bit)
                }
            }
        }

        if !ok {
            print("-1")
            exit(0)
        }
    }
}

// Output result
let output = B.map { String($0) }.joined(separator: " ")
print(output)
```

Notes:
- The algorithm handles M = 0 (no constraints) correctly; it outputs all zeros, which minimizes the sum.
- If any bit creates an inconsistency on any cycle, the program prints -1.

Idea:
A positive integer y is special iff y = 2^p · q^2 for some p ≥ 1, q ≥ 1.
Equivalently, if y = 2^e · m with m odd, then m must be a perfect square. So y is of the form
y = 2^e · t^2 with e ≥ 1 and t ≥ 1.

If we fix t, the valid e are those with 2^e ≤ N / t^2, i.e. e ≤ floor(log2(N / t^2)).
Thus for each odd t (since t^2 is the odd part), the count contributed is floor(log2(N / t^2)).

To avoid looping over all t, group t by the value k = floor(log2(N / t^2)).
For a given k ≥ 1, the t that satisfy k = floor(log2(N / t^2)) lie in:
sqrt(N / 2^{k+1}) < t ≤ sqrt(N / 2^k).

Let A = floor(sqrt(N / 2^{k+1})) and B = floor(sqrt(N / 2^k)).
Then t ∈ (A, B], and we only count odd t. The number of odd t in (A, B] is:
count = floor((B + 1) / 2) - floor(A / 2).

Contribution for this k is k · count. Sum this over k ≥ 1.

We can implement this efficiently by using bit shifts to compute floor(N / 2^k) as N >> k and a integer sqrt for the values, since N ≤ 1e18, so k only goes up to about 60.

Algorithm:
- Read N (u128 for safety).
- For k = 1 to 60:
  - a = floor_sqrt(N >> (k+1))
  - b = floor_sqrt(N >> k)
  - if b > a:
      start = a + 1
      end = b
      count = ((end + 1) / 2) - (start / 2)  // number of odd t in [start, end]
      ans += k * count
- Print ans

This runs in O(log N) time with small constants.

Rust 1.56 implementation:

```rust
use std::io::{self, Read};

fn isqrt(n: u128) -> u128 {
    if n == 0 { return 0; }
    let mut lo: u128 = 0;
    let mut hi: u128 = n;
    let mut ans: u128 = 0;
    while lo <= hi {
        let mid = (lo + hi) >> 1;
        let m2 = mid * mid;
        if m2 <= n {
            ans = mid;
            lo = mid + 1;
        } else {
            if mid == 0 { break; }
            hi = mid - 1;
        }
    }
    ans
}

fn main() {
    // Read input
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let n: u128 = input.trim().parse::<u128>().unwrap();

    let mut ans: u128 = 0;

    // k from 1 to about 60 is enough since N <= 1e18
    for k in 1..=60 {
        let a_in = n >> (k + 1);
        let b_in = n >> k;

        let a = isqrt(a_in);
        let b = isqrt(b_in);

        if b > a {
            let start = a + 1;
            let end = b;
            // count of odd numbers in [start, end] is ((end+1)/2) - (start/2)
            let count = ((end + 1) >> 1) - (start >> 1);
            ans += (k as u128) * count;
        }
        // else, no t for this k
    }

    println!("{}", ans);
}
```

Notes:
- We count only odd t implicitly by counting odd numbers in the interval.
- y is always even (p ≥ 1), and the odd part m = t^2 is a perfect square, ensuring y is counted exactly once.

Idea:
For a subarray [L, R], let D be the set of distinct values appearing there. The minimal number of erase steps g(L, R) equals the number of connected components in the value-line of D, where consecutive integers are connected. Equivalently:
- g(L, R) = number of blocks of consecutive values present in the subarray.

If D has k distinct values d1 < d2 < ... < dk, then a block is a maximal run where di+1 = di + 1. Therefore
g(L, R) = k - (# of i with di+1 = di + 1).

Hence the sum over all subarrays is:
Sum g = Sum over all subarrays (distinct count) - Sum over all subarrays (number of pairs (t, t+1) both present).

We can compute these two sums efficiently.

1) Sum over subarrays of distinct values (sum of distinct elements in all subarrays)
For each value v (1..N), count subarrays containing at least one occurrence of v. If positions of v are p1 < p2 < ... < pm, then subarrays not containing v are entirely within the gaps:
gap lengths: p1-1, p2-p1-1, ..., N - pm
The number of subarrays not containing v is sum over gaps of gap*(gap+1)/2. Total subarrays is N*(N+1)/2.
Thus subarrays containing at least one v = Total - sum_gaps(v).
Sum this over all v gives the total sum of distinct counts.

2) Sum over subarrays of (t, t+1) both present
For each t = 1..N-1, count subarrays that contain at least one t and at least one t+1. Using inclusion-exclusion:
Count(t, t+1) = Total - not_t - not_{t+1} + not_both_missing
where:
- not_t = sum_gaps(pos[t])
- not_{t+1} = sum_gaps(pos[t+1])
- not_both_missing = sum_gaps(pos[t] ∪ pos[t+1])
We can compute sum_gaps for a list of positions efficiently, and merge pos[t] and pos[t+1] in O(cnt[t] + cnt[t+1]) time to get not_both_missing.

Total time is O(N). All arithmetic fits in 64-bit.

Finally, answer = (sum over subarrays of distinct counts) - (sum over subarrays of (t, t+1) present).

Implementation (C++17):

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    if (!(cin >> N)) return 0;
    vector<int> S(N + 1);
    for (int i = 1; i <= N; ++i) cin >> S[i];

    // positions of each value
    vector<vector<int>> pos(N + 1);
    for (int i = 1; i <= N; ++i) {
        int v = S[i];
        pos[v].push_back(i);
    }

    long long Total = 1LL * N * (N + 1) / 2;

    auto sum_gaps = [&](const vector<int>& P) -> long long {
        if (P.empty()) return Total;
        long long sum = 0;
        int prev = 0;
        for (int p : P) {
            int gap = p - prev - 1;
            sum += 1LL * gap * (gap + 1) / 2;
            prev = p;
        }
        int gap = N - prev;
        sum += 1LL * gap * (gap + 1) / 2;
        return sum;
    };

    // precompute sum_gaps for each value
    vector<long long> sumNot(N + 1, 0);
    for (int v = 1; v <= N; ++v) {
        sumNot[v] = sum_gaps(pos[v]);
    }

    // DistinctSum: sum over v of (Total - sumNot[v])
    long long DistinctSum = 0;
    for (int v = 1; v <= N; ++v) DistinctSum += ( Total - sumNot[v] );

    // Adjacent-consecutive sum
    long long AdjSum = 0;
    for (int t = 1; t <= N - 1; ++t) {
        const auto &A = pos[t];
        const auto &B = pos[t + 1];

        long long notA = sumNot[t];
        long long notB = sumNot[t + 1];

        // not_both_missing = sum_gaps(A ∪ B) via merging A and B
        long long notBothMissing = 0;
        int i = 0, j = 0;
        int last = 0;
        while (i < (int)A.size() || j < (int)B.size()) {
            int cur;
            if (j == (int)B.size() || (i < (int)A.size() && A[i] < B[j])) {
                cur = A[i++];
            } else {
                cur = B[j++];
            }
            int gap = cur - last - 1;
            notBothMissing += 1LL * gap * (gap + 1) / 2;
            last = cur;
        }
        int gap = N - last;
        notBothMissing += 1LL * gap * (gap + 1) / 2;

        long long cnt = Total - notA - notB + notBothMissing;
        AdjSum += cnt;
    }

    long long ans = DistinctSum - AdjSum;
    cout << ans << "\n";
    return 0;
}
```

Notes:
- Uses 64-bit integers (long long) throughout to avoid overflow.
- Time complexity: O(N), since each position participates in only a couple of merges.
- Memory: O(N) for storing positions.
